"""Minimal abstractions (interfaces) to decouple core components."""

from abc import ABC, abstractmethod
from typing import List, Optional, Union

from .models import Coin, Pair


class DatabaseInterface(ABC):
    """Interface for database operations."""

    @abstractmethod
    def get_coins(self, only_enabled: bool = True) -> List[Coin]:
        """Get list of coins."""

    @abstractmethod
    def get_coin(self, coin: Union[Coin, str]) -> Coin:
        """Get a specific coin."""

    @abstractmethod
    def set_current_coin(self, coin: Union[Coin, str]):
        """Set the currently held coin."""

    @abstractmethod
    def get_current_coin(self) -> Optional[Coin]:
        """Get the currently held coin."""

    @abstractmethod
    def get_pairs_from(self, from_coin: Union[Coin, str], only_enabled: bool = True) -> List[Pair]:
        """Get pairs starting from a specific coin."""

    @abstractmethod
    def log_scout(
        self,
        pair: Pair,
        target_ratio: float,
        current_coin_price: float,
        other_coin_price: float,
    ):
        """Log scout action."""

    @abstractmethod
    def set_coins(self, symbols: List[str]):
        """Set up coins in the database."""


class ConfigInterface(ABC):
    """Interface for configuration."""

    @abstractmethod
    def get(self, key: str, fallback=None):
        """Get a config value."""

    @property
    @abstractmethod
    def BRIDGE(self) -> Coin:
        """Get the bridge coin."""

    @property
    @abstractmethod
    def BRIDGE_SYMBOL(self) -> str:
        """Get the bridge symbol."""

    @property
    @abstractmethod
    def SUPPORTED_COIN_LIST(self) -> List[str]:
        """Get list of supported coins."""

    @property
    @abstractmethod
    def SCOUT_MARGIN(self) -> float:
        """Get scout margin."""

    @property
    @abstractmethod
    def SCOUT_MULTIPLIER(self) -> float:
        """Get scout multiplier."""

    @property
    @abstractmethod
    def STRATEGY(self) -> str:
        """Get strategy name."""
